window.OSHA_QUESTIONS_SET5 = [
  { id: "sa-01", category: "sanitation", topic: "Agua potable", q: "En una obra de construcción, el agua potable debe:", choices: ["Proporcionarse, y los recipientes deben estar claramente marcados; está prohibida una taza común para beber", "Ser opcional si hay una gasolinera cerca", "Compartirse de un solo cucharón", "Ser solo refresco embotellado"], a: 0, why: "1926.51(a): agua potable, recipientes sanitarios, de un solo uso o fuente sanitaria: no taza común." },
  { id: "sa-02", category: "sanitation", topic: "Sanitarios en construcción", q: "Las instalaciones sanitarias en construcción se exigen en general a:", choices: ["20 empleados o menos: al menos un sanitario; luego según la tabla (p. ej., 1 por 40, etc.)", "Solo si el trabajo dura más de un año", "Nunca en trabajo de carretera", "Un sanitario para 500 trabajadores siempre basta"], a: 0, why: "1926.51(c): sanitarios en la obra salvo que los empleados puedan usar instalaciones cercanas. El número escala con la plantilla." },
  { id: "sa-03", category: "sanitation", topic: "Lavado", q: "Se exigen instalaciones de lavado cuando:", choices: ["Los trabajadores están expuestos a contaminantes dañinos (plomo, concreto, químicos) según se especifica en las normas de saneamiento y de sustancias", "Nunca", "Solo en oficinas", "Solo después de que OSHA lo cite"], a: 0, why: "1926.51(f) y reglas específicas de sustancias (plomo, sílice, cadmios): lávese para que los trabajadores no coman contaminación." },
  { id: "sa-04", category: "sanitation", topic: "Comer", q: "Los empleados no comerán ni beberán en áreas:", choices: ["Expuestas a materiales tóxicos", "Que son comedores limpios", "Al aire libre a la sombra con agua potable", "Con lavado de manos disponible y sin contaminación"], a: 0, why: "1926.51(g) / 1910.141: no alimentos en baños ni áreas con exposición tóxica. El plomo y el asbesto añaden higiene más estricta." },
  { id: "sa-05", category: "sanitation", topic: "Alimañas", q: "Todo lugar de trabajo cerrado se construirá, equipará y mantendrá, en la medida razonablemente practicable, para impedir:", choices: ["La entrada o el refugio de roedores, insectos y otras alimañas", "Toda la fauna silvestre, incluidas las aves a cualquier distancia", "El uso de botes de basura", "La ventilación natural"], a: 0, why: "1910.141(a)(5): control de alimañas. La construcción 1926.51 exige de modo similar la limpieza." },
  { id: "sa-06", category: "sanitation", topic: "Sanitarios de IG", q: "En industria general, los cuartos de sanitarios deben estar:", choices: ["Proporcionados de acuerdo con las tablas de 1910.141, mantenidos limpios y no usados como hábito para almacenar químicos peligrosos", "Opcionales con más de 10 empleados", "Un cubículo compartido para 200 como mínimo federal siempre", "Con candado desde afuera durante el turno"], a: 0, why: "1910.141(c): número de inodoros según la cantidad de empleados. Cuartos separados para cada sexo con excepciones para sitios pequeños." },
  { id: "sa-07", category: "sanitation", topic: "No potable", q: "El agua no potable (para combate de incendios o uso industrial) debe estar:", choices: ["Claramente marcada como no para beber, lavar ni cocinar", "Usada en el enfriador si se añade hielo", "Sin etiqueta", "Igual que el agua potable si se ve clara"], a: 0, why: "1926.51(b): salidas rotuladas. Están prohibidas las conexiones cruzadas con sistemas potables." },
  { id: "sa-08", category: "sanitation", topic: "Duchas", q: "Cuando una norma exige duchas (por ejemplo cierto trabajo de plomo o asbesto):", choices: ["El empleador las proporciona, jabón y vestidores según se especifique para que la ropa de calle se mantenga limpia", "Los trabajadores se duchan solo en casa como todo el programa", "Una botella de agua basta", "Una manguera de jardín en el estacionamiento siempre cumple la norma"], a: 0, why: "Las instalaciones de higiene específicas de sustancias impiden la exposición que se lleva a casa a las familias." },

  { id: "sg-01", category: "signs", topic: "Rótulos de prevención de accidentes", q: "Las tres clasificaciones de rótulos de prevención de accidentes de OSHA son:", choices: ["Danger, Caution e instrucción de seguridad (más peligro biológico donde se exija)", "Stop, Yield y Merge", "Rojo, azul y marrón solo como señales de tráfico", "Exit, Enter y Wait"], a: 0, why: "1926.200 / 1910.145: Danger (peligro inmediato), Caution (peligro potencial), instrucción de seguridad. Biohazard para BBP." },
  { id: "sg-02", category: "signs", topic: "Rótulo Danger", q: "Un rótulo Danger se usa cuando:", choices: ["Existe un peligro inmediato", "Se necesita un recordatorio de estacionamiento", "Solo para salidas", "El área es segura"], a: 0, why: "Rótulos rojos DANGER para peligro inmediato. No los use en exceso o pierden significado." },
  { id: "sg-03", category: "signs", topic: "Rótulo Caution", q: "Un rótulo Caution advierte de:", choices: ["Un peligro potencial o una práctica insegura", "Solo una zona de muerte inmediata", "El menú del almuerzo", "Citaciones de OSHA"], a: 0, why: "CAUTION amarillo. Ejemplo: piso mojado, tráfico de montacargas." },
  { id: "sg-04", category: "signs", topic: "Barricadas", q: "Las barricadas en obras de construcción deben estar:", choices: ["Visibles y usadas para advertir de peligros (huecos, tráfico, desniveles)", "Hechas de cinta de precaución como único sistema para un hueco de 20 pies", "Opcionales de noche", "Iguales que un barandal para protección contra caídas"], a: 0, why: "1926.202 / MUTCD para tráfico. La cinta no es un barandal y no es una cubierta de hueco." },
  { id: "sg-05", category: "signs", topic: "Banderillero", q: "Un banderillero en un trabajo de carretera debe:", choices: ["Estar capacitado, usar paletas/banderas adecuadas y prendas de alta visibilidad según MUTCD / 1926.201", "Usar ropa oscura para confundirse", "Pararse en el carril de circulación sin ruta de escape", "Usar un teléfono celular como señal principal"], a: 0, why: "1926.201: señalización. Alta visibilidad, capacitación y una posición segura. Los golpes (struck-by) son un asesino Focus Four en zonas de trabajo." },
  { id: "sg-06", category: "signs", topic: "Tráfico", q: "Cuando el trabajo de construcción afecta el tráfico público, el empleador debe:", choices: ["Usar señales de tráfico, semáforos y barricadas que cumplan el MUTCD según exigen 1926.200–203", "Depender solo de trabajadores que agitan los brazos", "Apagar todas las luces para que los conductores reduzcan la velocidad", "Dejar un solo cono a una milla"], a: 0, why: "Subparte G. El trabajo nocturno necesita iluminación y dispositivos retrorreflectantes." },
  { id: "sg-07", category: "signs", topic: "Rótulo de salida", q: "Los rótulos de salida deben estar:", choices: ["Claramente visibles, iluminados según se exija y no obstruidos ni confundidos con decoraciones", "Siempre del mismo color que los rótulos Danger", "Opcionales en almacenes", "Escondidos por seguridad"], a: 0, why: "1910.37(b): cada salida debe ser visible y estar marcada. Ningún mobiliario que oscurezca la ruta." },
  { id: "sg-08", category: "signs", topic: "Carga de piso", q: "En edificios, la clasificación de carga de los pisos puede necesitar estar:", choices: ["Publicada donde la norma lo exige (p. ej., 1910.22(d) para ciertas ocupaciones)", "Mantenida en secreto", "Pintada en cada 2x4", "Solo en la oficina del arquitecto"], a: 0, why: "Conozca los límites de carga del área de almacenamiento para que los racks y las tarimas no derrumben un piso." },

  { id: "vh-01", category: "vehicles", topic: "Vehículos de construcción", q: "Los vehículos de motor usados en una obra de construcción (fuera de carretera) deben tener:", choices: ["Luces de freno que funcionen, alarma audible de retroceso u observador equivalente, y asientos/cinturones según se especifica en 1926.601", "Ninguna luz si se usan solo de día siempre", "Un CDL para cada camioneta en el sitio siempre", "Nunca inspección"], a: 0, why: "1926.601: vehículos generales de construcción. 1926.602 cubre equipo de movimiento de tierra." },
  { id: "vh-02", category: "vehicles", topic: "Alarma de retroceso", q: "El equipo de movimiento de tierra con vista trasera obstruida debe tener:", choices: ["Una alarma de retroceso audible por encima del ruido circundante, o un observador", "Solo una calcomanía", "Ninguna advertencia si el operador toca la bocina a veces", "Una radio sonando"], a: 0, why: "1926.602(a)(9): alarmas de retroceso. Los vigías deben estar a la vista del operador." },
  { id: "vh-03", category: "vehicles", topic: "Volcadura", q: "Los ROPS (estructuras de protección contra volcadura) se exigen en muchos tipos de:", choices: ["Equipo de manejo de materiales y movimiento de tierra listado en 1926.1000–1003 / 1926.602", "Todos los autos de pasajeros", "Sillas de oficina", "Escaleras de tijera"], a: 0, why: "Cinturones con ROPS. No salte de una máquina que se vuelca." },
  { id: "vh-04", category: "vehicles", topic: "Caminos de acarreo", q: "El equipo en caminos de acarreo debe:", choices: ["Operarse dentro de pendientes, anchos y reglas que impidan descontrol y colisiones; ningún pasajero en las cargas", "Viajar cualquier pendiente sin capacidad de retardo", "Llevar personas extra en el cucharón", "Desactivar las alarmas de retroceso de noche"], a: 0, why: "1926.602: caminos de acceso, pendientes y ningún pasajero no autorizado." },
  { id: "vh-05", category: "vehicles", topic: "Despeje", q: "Antes de mover un camión de volteo o un trailer, el operador debe:", choices: ["Revisar líneas aéreas, personas y que la caja/compuerta esté despejada: las cajas elevadas golpean líneas eléctricas", "Elevar la caja mientras conduce bajo líneas para volcar más rápido", "Asumir que el vigía ve todo desde la cabina", "Enviar mensajes de texto mientras retrocede"], a: 0, why: "Las cajas de volteo elevadas son un patrón clásico de electrocución y golpe aéreo." },
  { id: "vh-06", category: "vehicles", topic: "Estacionar equipo", q: "Al estacionar equipo de construcción, baje cuchillas/cucharones y ponga el freno de estacionamiento:", choices: ["Sí: impida el descontrol y las lesiones por aplastamiento", "Deje el cucharón elevado como un dosel", "Estacione en una pendiente en neutro sin calzos", "Déjelo encendido desatendido siempre"], a: 0, why: "Baje los implementos, calce si se necesita y no deje equipo encendido como calentador para una siesta." },
  { id: "vh-07", category: "vehicles", topic: "Cinturones en equipo", q: "Donde hay ROPS instalado, los operadores deben:", choices: ["Usar el cinturón", "Quitar el cinturón para poder saltar", "Pararse mientras operan", "Desactivar el interruptor"], a: 0, why: "El cinturón lo mantiene en la zona de protección. Saltar es cómo las personas quedan aplastadas." },
  { id: "vh-08", category: "vehicles", topic: "Vías públicas", q: "Cuando los vehículos de construcción entran a vías públicas deben:", choices: ["Seguir las leyes de tráfico, estar iluminados/marcados según se exija y ceder: una alarma de retroceso no es licencia para entrar a ciegas", "Asumir siempre el derecho de paso", "Viajar en reversa en la carretera como práctica estándar", "Ignorar a los banderilleros"], a: 0, why: "Golpes (struck-by) en las entradas del sitio. Use banderilleros y señales de camión que entra." },
  { id: "vh-09", category: "vehicles", topic: "Viaje de grúa", q: "Viajar una grúa con una carga o con la pluma arriba:", choices: ["Siga los procedimientos de viaje del fabricante; muchas izadas exigen la carga en el gancho solo cuando está instalada, no mientras se desplaza por carretera", "Siempre viaje a velocidad de carretera con una pluma larga", "No necesita vigía para líneas aéreas", "Siempre es más seguro que llevar la carga en un camión"], a: 0, why: "Viaje y ensamblaje/desensamblaje de la Subparte CC. Líneas aéreas y volcadura en pendientes." },
  { id: "vh-10", category: "vehicles", topic: "Inspeccionar vehículo", q: "Al inicio de cada turno, los vehículos en uso se revisarán para asegurar:", choices: ["Que las partes, accesorios y equipo que afectan la operación segura estén en condición adecuada de operación", "Que solo funcione la radio", "Que el portavasos esté limpio", "Nada: bastan las visitas anuales al taller"], a: 0, why: "1926.601(b)(14): inspección de turno. Retire de servicio los vehículos defectuosos." },

  { id: "er-01", category: "ergonomics", topic: "Sin norma de ergonomía", q: "OSHA no tiene actualmente una norma integral de ergonomía. Los peligros de TME se atienden con:", choices: ["La Cláusula de deber general, directrices y algunas reglas específicas de industria", "Un código detallado 1910.900 que cita cada levantamiento", "Ignorar las lesiones de espalda", "Solo compensación laboral, nunca OSHA"], a: 0, why: "Los almacenes, la enfermería y el levantamiento en construcción igual reciben citaciones de Deber general cuando los peligros se reconocen y existen controles factibles." },
  { id: "er-02", category: "ergonomics", topic: "Levantamiento NIOSH", q: "El límite de peso recomendado de la ecuación de levantamiento de NIOSH para un levantamiento ideal es de unos:", choices: ["51 libras (23 kg) en condiciones ideales, reducido por multiplicadores de alcance, frecuencia y giro", "100 libras para todos", "Siempre 10 libras", "No existe un límite recomendado"], a: 0, why: "OSHA no establece un PEL de 51 lb, pero el RWL de NIOSH es el número habitual de capacitación. Levantamiento en equipo, ayudas mecánicas y mantenga las cargas cerca." },
  { id: "er-03", category: "ergonomics", topic: "Levantamiento seguro", q: "Un levantamiento manual más seguro en general usa:", choices: ["Carga cerca del cuerpo, postura estable, sin giro y ayuda mecánica cuando es pesada o incómoda", "Un giro brusco en la cintura", "Alcanzar sobre una mesa a distancia de los brazos a diario como método", "Aguantar la respiración y jalar de golpe"], a: 0, why: "El block, el drywall y el refuerzo de construcción son fuentes clásicas de TME. Use diablitos, montacargas y levantamientos de dos personas." },
  { id: "er-04", category: "ergonomics", topic: "Repetición", q: "La fuerza muy repetitiva con mala postura puede causar:", choices: ["Esguinces, distensiones y trastornos musculoesqueléticos (TME)", "Solo pérdida auditiva", "Derrumbes", "Arco eléctrico"], a: 0, why: "La rotación de puestos, los descansos, los mangos de herramientas y la altura del puesto de trabajo son controles administrativos/de ingeniería." },
  { id: "er-05", category: "ergonomics", topic: "Vibración", q: "La vibración mano-brazo de esmeriladoras y rompedoras puede causar:", choices: ["Dedo blanco por vibración / HAVS: use herramientas antivibración, guantes como complemento y limite el tiempo de gatillo", "Mejor circulación", "Ningún efecto crónico", "Solo ruido"], a: 0, why: "Herramientas de baja vibración, mantenimiento y manos calientes. Los guantes no eliminan la necesidad de reducir la vibración en la fuente." },
  { id: "er-06", category: "ergonomics", topic: "Trabajo por encima de la cabeza", q: "Trabajar con las manos por encima de los hombros durante períodos largos:", choices: ["Aumenta el riesgo de TME de hombro/cuello; use plataformas, andamios a la altura correcta y rotación de puestos", "Es la postura más saludable", "Solo afecta los pies", "OSHA lo exige para todos los oficios"], a: 0, why: "Coloque el trabajo a la altura del codo cuando pueda. Las plataformas de tijera y los andamios baker existen por una razón." },
  { id: "er-07", category: "ergonomics", topic: "Empujar vs jalar", q: "Al mover carritos, en general es mejor:", choices: ["Empujar que jalar, con una carga que pueda controlar y una ruta despejada", "Jalar una pila que no puede ver por encima", "Empujar con la espalda baja doblada y torcida", "Montarse en el carrito cuesta abajo"], a: 0, why: "Empujar usa el peso del cuerpo y le permite ver. Mantenga las ruedas en buen estado." },
  { id: "er-08", category: "ergonomics", topic: "Reporte temprano", q: "Los trabajadores deben reportar síntomas de TME:", choices: ["Temprano, para que el trabajo pueda modificarse antes de una distensión registrable", "Solo después de que no puedan trabajar", "Nunca, por los incentivos", "Solo en redes sociales"], a: 0, why: "Aplica la antirrepresalia. El reporte temprano es una fortaleza del programa, no un fracaso." },

  { id: "dm-13", category: "demolition", topic: "Pisos cargados", q: "No se permitirá que los escombros se acumulen hasta el punto de que:", choices: ["Sobrecarguen los pisos o creen un peligro de colapso/incendio", "Solo se vean desordenados", "Ayuden a apuntalar muros", "Reemplacen el lastre"], a: 0, why: "1926.850 y orden y limpieza. Conozca la carga del piso. Los escombros mojados pesan más." },
  { id: "dm-14", category: "demolition", topic: "Grúa de bola", q: "La bola de demolición no debe usarse cuando:", choices: ["La grúa no está diseñada para bolas, o el operador no puede controlar el balanceo hacia áreas ocupadas", "La estructura está aislada y la grúa está clasificada", "Existe un plan de izaje y el área está despejada", "Hay líneas de guía y zonas de exclusión"], a: 0, why: "1926.859: la bola no debe usarse cuando el clima o el control son inadecuados. Nunca use bola en una grúa no diseñada para ello." },
  { id: "dm-15", category: "demolition", topic: "Pasillos en demolición", q: "Se exige iluminación adecuada durante la demolición para que:", choices: ["Los trabajadores puedan ver huecos, desniveles y miembros restantes", "El trabajo se vea bien en cámara solamente", "Los murciélagos se mantengan lejos", "Las inspecciones nocturnas de OSHA sean opcionales"], a: 0, why: "1926.850(n) y 1926.26: iluminación. Los sitios de demolición están llenos de huecos sin marcar." },
  { id: "dm-16", category: "demolition", topic: "Entrada de empleados", q: "Solo se permitirá en el área a los empleados necesarios para la demolición cuando:", choices: ["Se estén jalando o dejando caer muros o miembros", "Se sirve el almuerzo", "El estudio se está redactando fuera del sitio", "Los servicios ya están muertos y el edificio es un estacionamiento"], a: 0, why: "Mantenga a espectadores y oficios extra fuera del radio de colapso." },
  { id: "dm-17", category: "demolition", topic: "Muros de mampostería en demolición", q: "No se permitirá que los muros de mampostería caigan sobre los pisos de un edificio en masas tales que excedan:", choices: ["La capacidad segura de carga del piso", "Un ladrillo", "El peso de la grúa", "Siempre una camioneta"], a: 0, why: "1926.854: capacidad del piso. Demolición secuencial." },
  { id: "dm-18", category: "demolition", topic: "Columna húmeda", q: "Durante la demolición de un edificio con columna húmeda, la protección contra incendios puede necesitar:", choices: ["Mantenerse según lo exija el código de incendio / 1926.850 según aplique hasta que se convierta en un peligro en sí", "Quitarse primero siempre", "Usarse para inundar cada piso solo por el polvo", "Ignorarse"], a: 0, why: "Coordine con el departamento de bomberos. El trabajo en caliente más los escombros de demolición es una carga de incendio." },

  { id: "tl-13", category: "tools", topic: "Interruptores", q: "Las sierras circulares, las motosierras y las herramientas de percusión deben tener:", choices: ["Un interruptor de presión constante que se apaga al soltarse (con excepciones especificadas)", "Un gatillo de bloqueo encendido como único control permitido para sierras circulares", "Ningún interruptor para que corran de forma continua", "Un interruptor que se queda pegado encendido por conveniencia"], a: 0, why: "1926.300(d) / 1910.243: controles de encendido-apagado. Muchas sierras circulares no pueden tener bloqueo encendido." },
  { id: "tl-14", category: "tools", topic: "Motosierra", q: "Los usuarios de motosierra deben:", choices: ["Conocer las zonas de rechazo, mantener ambas manos en la sierra y usar chaparreras/protección de ojos/oídos/cabeza según se exija", "Cortar con la punta de la barra como método normal", "Sostener la sierra con una mano por encima de la cabeza", "Desactivar el freno de cadena"], a: 0, why: "El rechazo mata. La madera de construcción y las sierras de demolición igual rechazan. EPP más técnica." },
  { id: "tl-15", category: "tools", topic: "Blindaje de carga explosiva", q: "Al disparar una herramienta de carga explosiva, el operador debe:", choices: ["Tener la herramienta perpendicular y el escudo en su lugar; no dispare hacia material que se astilla o extra-duro/blando contrario a las instrucciones", "Disparar alrededor de las esquinas", "Usarla como martillo en fallos de disparo de inmediato", "Dejarla cargada en un andamio"], a: 0, why: "1926.302(e): inspeccionar la herramienta dos veces al día, y no disparar hacia materiales que podrían permitir que el fijador pase a un área ocupada." },
  { id: "tl-16", category: "tools", topic: "Tierra de herramientas eléctricas", q: "Una herramienta de tres hilos con la pata de tierra faltante debe:", choices: ["Retirarse de servicio", "Usarse con un adaptador tramposo", "Cubrirse con cinta y devolverse a servicio", "Usarse solo al aire libre"], a: 0, why: "La trayectoria de tierra se fue. Las herramientas de dos hilos de doble aislamiento son distintas: busque la marca de caja dentro de caja." },
  { id: "tl-17", category: "tools", topic: "Bloquear gatos hidráulicos", q: "Después de que un gato eleva una carga, usted debe:", choices: ["Apuntalar o bloquear la carga; no dependa del gato como único apoyo mientras trabaja debajo", "Arrastrarse debajo con el gato como único apoyo", "Patear el gato", "Exceder la capacidad nominal si la carga está casi arriba"], a: 0, why: "1926.305: bloqueo. Los gatos bajan por fuga." },
  { id: "tl-18", category: "tools", topic: "Pistola de clavos", q: "Las clavadoras neumáticas deben:", choices: ["Desconectarse cuando están desatendidas; nunca apuntarse a personas; los gatillos secuenciales reducen las lesiones de disparo por golpe", "Llevarse con un dedo en el gatillo como estándar", "Usarse para colgar herramientas en la ropa de un compañero", "Tener la manguera latigando libremente sin retenedores"], a: 0, why: "Modos de contacto de trabajo y disparo secuencial. Protección ocular. OSHA y NIOSH tienen orientación sobre pistolas de clavos." },
  { id: "tl-19", category: "tools", topic: "Corte abrasivo", q: "Las ruedas de corte abrasivo en una sierra de corte:", choices: ["Necesitan el resguardo; no esmerile en el lado de una rueda no clasificada para ello; deje que la rueda se detenga antes de asentar la sierra", "Deben tener el resguardo quitado para una vista completa", "Siempre pueden cargarse de lado como un disco de esmerilar", "No necesitan coincidencia de RPM"], a: 0, why: "Las ruedas que revientan envían fragmentos a alta velocidad. La prueba de sonido y la coincidencia de RPM siguen aplicando." },
  { id: "tl-20", category: "tools", topic: "Condición de sierra de mano", q: "Una sierra de mano con una hoja desafilada, doblada o sin asegurar:", choices: ["Es más probable que se atasque y corte al usuario: repare o reemplace", "Es más segura porque es lenta", "Cumple OSHA tal como está", "Debe usarse sin mango para control"], a: 0, why: "1926.301: mangos en limas y herramientas. Las herramientas afiladas son más seguras que las desafiladas que resbalan." },

  { id: "fa-11", category: "firstaid", topic: "Proximidad cercana", q: "OSHA ha descrito “proximidad cercana” para atención médica en algunas interpretaciones como:", choices: ["Unos 3–4 minutos para amenaza de vida, y hasta 15 minutos para no amenaza de vida en algunas cartas: igual tenga primeros auxilios capacitados si no puede depender de eso", "2 horas siempre está bien", "Solo 911 sin suministros jamás", "Una clínica en el siguiente condado siempre cuenta"], a: 0, why: "La construcción remota y la tala necesitan primeros auxilios en el sitio. No asuma que una ambulancia ganará a un sangrado en un patio de aserradero." },
  { id: "fa-12", category: "firstaid", topic: "Números publicados", q: "Los números de teléfono de médicos, hospitales y ambulancias deben estar:", choices: ["Publicados de forma visible donde 1926.50 lo exige", "Solo en la cabeza del superintendente", "En un teléfono que está muerto", "Opcionales en trabajos de carretera"], a: 0, why: "1926.50(f): publicación. La cobertura celular no está garantizada: tenga un plan." },
  { id: "fa-13", category: "firstaid", topic: "Camillas", q: "En sitios donde las camillas se exigen por la naturaleza del trabajo, deben estar:", choices: ["Disponibles y la cuadrilla debe saber cómo usarlas sin empeorar una lesión de columna", "Usadas como andamio", "Dejadas en el taller", "Improvisadas de refuerzo siempre"], a: 0, why: "Apéndice de 1926.50(d) y práctica de trabajo remoto. Capacite antes de necesitarlo." },
  { id: "fa-14", category: "firstaid", topic: "Quemaduras térmicas", q: "Para quemaduras térmicas, los primeros auxilios en general incluyen:", choices: ["Enfriar con agua, cubrir de forma suelta, no reventar ampollas, buscar atención médica para quemaduras graves", "Mantequilla y hielo directamente en quemaduras abiertas como método preferido", "Algodón empapado en solvente", "Ignorar las quemaduras eléctricas porque la piel se ve bien"], a: 0, why: "Las quemaduras eléctricas y químicas necesitan cuidado extra. En caso de duda, EMS." },
  { id: "fa-15", category: "firstaid", topic: "RCP AED", q: "Después de un paro cardíaco en el lugar de trabajo, la supervivencia mejora con:", choices: ["911 temprano, RCP y descarga de AED si está indicada", "Esperar a ver si despiertan en 20 minutos", "Pasearlos", "Dar solo agua"], a: 0, why: "Los minutos importan. Incluya AED en el EAP si los tiene y capacite." },

  { id: "sw-11", category: "stairways", topic: "Agarre del pasamanos", q: "Un pasamanos de escalera debe ser:", choices: ["Agarrable, entre unas 30 y 37 pulgadas desde la huella, y capaz de resistir la fuerza especificada", "Un 2x4 puesto plano como el riel agarrable preferido siempre", "Opcional si los trabajadores son jóvenes", "De 60 pulgadas de alto como un barandal superior"], a: 0, why: "1926.1052(c): altura, despeje de las paredes y fuerza de 200 lb similar a los barandales en algunos aspectos. Superficie lisa." },
  { id: "sw-12", category: "stairways", topic: "Lados sin protección", q: "Los lados y bordes sin protección de los descansos de escalera se:", choices: ["Proporcionarán con un sistema de barandal", "Marcarán con tiza", "Dejarán abiertos para acopio de materiales", "Protegerán solo con cinta de precaución"], a: 0, why: "1926.1052(c)(12): bordes de descanso. Especificaciones de barandal de la Subparte M." },
  { id: "sw-13", category: "stairways", topic: "Puertas en descansos", q: "Las puertas que se abren hacia un descanso de escalera no deben:", choices: ["Reducir el ancho efectivo del descanso por debajo del mínimo requerido cuando la puerta está abierta", "Existir", "Tener herraje antipánico", "Balancearse en absoluto"], a: 0, why: "1926.1052(a)(4): el descanso debe seguir siendo lo bastante grande con la puerta abierta." },
  { id: "sw-14", category: "stairways", topic: "Charola metálica temporal", q: "Hasta que las charolas se llenen, los trabajadores que usan escaleras de charola metálica necesitan:", choices: ["Relleno temporal (madera u otro) para que la charola no sea una trampa abierta", "Caminar solo por las zancas", "Ninguna medida extra", "Saltar de charola a charola"], a: 0, why: "Las charolas vacías son un peligro clásico de pierna rota." },
  { id: "sw-15", category: "stairways", topic: "Iluminación de escaleras", q: "Las escaleras fijas en uso se:", choices: ["Iluminarán para que los trabajadores puedan ver huellas y peligros", "Dejarán oscuras para ahorrar energía", "Usarán para almacenar cimbra", "Hielarán para tracción"], a: 0, why: "Tablas de iluminación 1926.56 más orden y limpieza. Las escaleras de construcción son un lugar frecuente de caídas." },

  { id: "ww-16", category: "walking", topic: "1910.22 general", q: "Las superficies de trabajo y circulación en IG deben inspeccionarse:", choices: ["Con regularidad y según se necesite, y las condiciones peligrosas corregirse o resguardarse", "Nunca", "Solo después de una fatalidad", "Una vez cuando el edificio es nuevo"], a: 0, why: "1910.22(d): inspeccione. Las cubiertas, los barandales y el orden y limpieza son deberes del día a día." },
  { id: "ww-17", category: "walking", topic: "Escalera IG 24 pies", q: "Una escalera fija en industria general que se extiende más de 24 pies sobre un nivel inferior en general necesita:", choices: ["Un sistema personal de detención de caídas o un sistema de seguridad de escalera (las jaulas se están eliminando gradualmente como medio principal)", "Solo pintura", "Una soga", "Nada si la usan contratistas"], a: 0, why: "1910.28(b)(9): fechas de transición. Las escaleras nuevas no pueden depender solo de jaulas." },
  { id: "ww-18", category: "walking", topic: "Dueño del edificio de descenso por cuerda", q: "Antes de permitir el descenso por cuerda, el dueño del edificio debe:", choices: ["Proporcionar información escrita de que los anclajes se han identificado, probado, certificado y mantenido", "No hacer nada: es solo problema del contratista", "Prohibir el lavado de ventanas", "Proporcionar un solo tubo sin probar"], a: 0, why: "1910.27(b): deberes del dueño del edificio. Los contratistas igual inspeccionan su propio equipo RDS." },
  { id: "ww-19", category: "walking", topic: "Andamios IG", q: "Los andamios en industria general (no construcción) en general siguen:", choices: ["1910 Subparte D de trabajo y circulación más reglas del fabricante; muchos empleadores igual usan prácticas de 1926 Subparte L", "Ninguna regla", "Solo códigos de incendio", "Zanjas de 1926 Subparte P"], a: 0, why: "1910.27–28 abordan algunos asuntos de andamio/escalera. Los andamios de construcción siguen siendo 1926.451 cuando es trabajo de construcción." },
  { id: "ww-20", category: "walking", topic: "Objetos que caen IG", q: "Cuando hay un peligro de objetos que caen, los empleadores de IG deben:", choices: ["Proteger a los trabajadores con rodapiés, pantallas, dosel o barricadas según se especifica en 1910.28", "Depender siempre solo de cascos como el sistema completo", "Gritar “cuidado” como el control de ingeniería", "Quitar todos los rodapiés por limpieza"], a: 0, why: "Los cascos son EPP, últimos en la jerarquía. Mantenga a las personas fuera de la zona de caída." },

  { id: "st-16", category: "steel", topic: "Sujeciones de deck", q: "El decking metálico se colocará de forma apretada y se asegurará de inmediato para impedir:", choices: ["El desplazamiento accidental y como superficie de trabajo en la medida practicable", "Toda soldadura", "El uso de protección contra caídas", "Las líneas de guía"], a: 0, why: "1926.754(e): decking. No deje láminas sueltas como una vela en el viento." },
  { id: "st-17", category: "steel", topic: "Hueco de techo en acero", q: "Los huecos en el deck metálico durante el montaje de acero deben estar:", choices: ["Protegidos por cubiertas, barandales o equivalente, incluidas las aberturas de tragaluces", "Dejados abiertos para HVAC después sin marca", "Cubiertos solo con aislamiento", "Ignorados por debajo de 15 pies"], a: 0, why: "Las mismas reglas de huecos más la Subparte R. Los tragaluces matan a montadores de acero y techadores." },
  { id: "st-18", category: "steel", topic: "Montaje de viguetas", q: "Una vigueta de acero no se colocará en ningún apoyo salvo que el apoyo esté:", choices: ["Estabilizado: no use viguetas sin arriostrar como pasarela", "Todavía en el camión", "Madera temporal de cualquier tamaño", "Una pila de decking"], a: 0, why: "1926.757: viguetas. Arriostramiento de montaje y protección contra caídas. Las viguetas ruedan y tiran a los trabajadores." },
  { id: "st-19", category: "steel", topic: "Empalme de columna", q: "Al hacer un empalme de columna, los trabajadores necesitan:", choices: ["Acceso adecuado y protección contra caídas; el miembro debe estar estable", "Pararse en el patín sin PFAS a 40 pies como método preferido", "Ningún perno si lo sostienen con la mano", "Un montacargas como única grúa"], a: 0, why: "Los conectores igual tienen umbrales de altura. La estabilidad de la pieza es trabajo del montador con la grúa." },
  { id: "st-20", category: "steel", topic: "Conexiones dobles", q: "En conexiones dobles viga-columna donde la viga no se ha empernado en el campo, se necesita un asiento, dispositivo de izaje o equivalente para que:", choices: ["La primera viga no pueda caer cuando se quitan los pernos compartidos para el segundo miembro", "La grúa pueda irse de inmediato", "No se use protección contra caídas", "Se pueda omitir el decking"], a: 0, why: "1926.756(c): conexiones dobles. Un patrón conocido de colapso/caída." },

  { id: "cn-16", category: "concrete", topic: "Losa izada", q: "Las operaciones de losa izada tienen requisitos extra que incluyen:", choices: ["Un PE, izaje sincronizado y ningún empleado bajo la losa durante el gato salvo los esenciales y protegidos según se especifique", "Trabajadores parados bajo la losa para vigilar los gatos", "Ningún dibujo", "Solo polipastos de cadena manuales"], a: 0, why: "1926.705: losa izada. Varios colapsos históricos. Manténgase fuera de debajo." },
  { id: "cn-17", category: "concrete", topic: "Apuntalamiento prefabricado", q: "Hasta que las conexiones permanentes estén completas, los muros prefabricados deben estar:", choices: ["Apuntalados para impedir el colapso por viento o impacto", "Autoportantes si se ven pesados", "Sostenidos por un peón", "Apoyados en desperdicios de madera"], a: 0, why: "1926.704: dibujos de montaje. El viento en un panel de muro es una vela." },
  { id: "cn-18", category: "concrete", topic: "Tapas de refuerzo", q: "La protección contra empalamiento en refuerzo vertical debe ser:", choices: ["Capaz de resistir el impacto de una caída: tapas o canaletas probadas/listadas, no hongos decorativos que fallan", "Cualquier tapa de plástico", "Pintura", "Opcional siempre por debajo de 6 pies aunque pueda caer sobre el acero"], a: 0, why: "OSHA ha enfatizado que algunas tapas “de hongo” no protegen. Use sistemas que funcionen. La protección contra caídas sigue aplicando a 6 pies en cimbra/refuerzo." },
  { id: "cn-19", category: "concrete", topic: "Inspección de cimbra", q: "Un diseñador calificado designado o un inspector calificado designado (según se especifique) debe inspeccionar el apuntalamiento:", choices: ["Inmediatamente antes, durante e inmediatamente después del colado de concreto", "Una vez solo al inicio del proyecto", "Nunca si el carpintero tiene experiencia", "Solo después de que el colado endurece"], a: 0, why: "1926.703(b): inspecciones. La sobrecarga y las riostras faltantes causan desastres." },
  { id: "cn-20", category: "concrete", topic: "Viento en mampostería", q: "Durante la construcción de mampostería, el viento puede:", choices: ["Derribar muros sin apuntalar: siga las reglas de apuntalamiento y LAZ aunque el muro tenga solo unos días", "Afectar solo el acero", "Nunca afectar el CMU", "Ignorarse siempre por debajo de 20 mph"], a: 0, why: "1926.706: zona de acceso limitado y apuntalamiento de más de 8 pies. La mampostería verde tiene poca resistencia a la tensión." },

  { id: "ae-16", category: "aerial", topic: "Interior vs exterior", q: "Algunas plataformas de tijera están clasificadas solo para interior porque:", choices: ["La carga de viento y las clasificaciones de rueda/superficie difieren: usar una máquina de interior afuera puede volcarla", "OSHA prohíbe todas las plataformas de exterior", "Las baterías solo funcionan en interiores", "Los barandales son más cortos al aire libre"], a: 0, why: "Lea la calcomanía. La clasificación de exterior incluye el viento. Las máquinas de interior en un estacionamiento con una ráfaga han matado gente." },
  { id: "ae-17", category: "aerial", topic: "Cadena de la puerta", q: "La puerta o cadena de la plataforma en un elevador debe estar:", choices: ["Cerrada cuando la plataforma está elevada", "Dejada abierta para fácil acceso a altura", "Usada como un peldaño", "Quitada si traquetea"], a: 0, why: "1926.453 y el fabricante: ocupación con la entrada cerrada. No salga trepando a un techo sin un plan y anclaje." },
  { id: "ae-18", category: "aerial", topic: "Persona en el piso", q: "Una persona en el piso debe saber:", choices: ["Cómo usar los controles de piso / el descenso de emergencia si el operador queda incapacitado", "Nada: no es su plataforma", "Solo cómo tomar fotos", "Cómo conducir la plataforma mientras hay gente en los barandales"], a: 0, why: "Plan de rescate. Llaves, e-stop y válvulas de descenso. No deje a un trabajador elevado solo sin una forma de bajar." },
  { id: "ae-19", category: "aerial", topic: "Mito del brazo aislado", q: "Un brazo “aislado” en una plataforma de renta de un contratista:", choices: ["No la hace segura para trabajar junto a líneas de distribución salvo que sea una cuadrilla calificada de despeje de líneas usando una unidad probada dentro de su clasificación", "Significa que los titulares de OSHA 10 pueden contactar líneas primarias", "Nunca necesita prueba dieléctrica", "Reemplaza la regla de 10 pies para todos"], a: 0, why: "La mayoría de las plataformas de brazo de construcción no se mantienen como dispositivos aéreos aislados. Manténgase lejos de las líneas." },
  { id: "ae-20", category: "aerial", topic: "Tabla de carga del brazo", q: "A medida que un brazo se extiende o la canastilla sube y sale, la capacidad por lo general:", choices: ["Disminuye: revise la tabla en esa geometría", "Aumenta", "Se queda igual que plegada", "Se duplica con dos trabajadores"], a: 0, why: "Brazo de momento. Dos trabajadores más un atado de tubería a máximo alcance es una volcadura esperando suceder." },

  { id: "cs-26", category: "confined", topic: "Anfitrión de construcción", q: "En una obra de construcción, el contratista controlador debe:", choices: ["Compartir información sobre espacios que requieren permiso y coordinar con otros contratistas bajo la Subparte AA", "Guardar silencio sobre fosos y tanques", "Solo el anfitrión en industria general tiene deberes, nunca la construcción", "Poner un letrero y no hacer nada más"], a: 0, why: "1926.1203: coordinar, informar y hacer el informe posterior. Múltiples empleadores crean lagunas." },
  { id: "cs-27", category: "confined", topic: "Monitoreo continuo", q: "Durante la entrada con permiso, la atmósfera se probará:", choices: ["Según se especifique en el permiso: a menudo de forma continua o con la frecuencia suficiente para advertir de cambios", "Una vez la semana anterior", "Nunca si olía bien", "Solo oxígeno si el espacio es un tanque que contuvo químicos"], a: 0, why: "Estratificación: pruebe a múltiples niveles. Medidores en la zona de respiración del entrante cuando sea posible." },
  { id: "cs-28", category: "confined", topic: "Inertización", q: "Inertizar un espacio con nitrógeno:", choices: ["Crea una atmósfera IDLH con deficiencia de oxígeno: trátela como inmediatamente peligrosa", "Hace el espacio seguro para entrar sin respirador", "Es lo mismo que ventilar con aire fresco", "Eleva el oxígeno por encima de 23.5%"], a: 0, why: "La inertización impide el incendio al quitar el oxígeno. Lo asfixiará. SCBA/SAR y permisos." },
  { id: "cs-29", category: "confined", topic: "Cancelar permiso", q: "El supervisor de entrada debe cancelar el permiso cuando:", choices: ["Las operaciones están completas o surge una condición no permitida por el permiso", "El asistente almuerza dentro del espacio", "Ha pasado una semana aunque la gente siga adentro", "El medidor nunca se usó"], a: 0, why: "1910.146(e)(5): termine y cierre el permiso. Vuelva a emitir después de reevaluar si el trabajo continúa." },
  { id: "cs-30", category: "confined", topic: "No autorizados", q: "Si personas no autorizadas se acercan a un espacio con permiso, el asistente debe:", choices: ["Advertirles que se mantengan lejos y notificar al supervisor según se necesite", "Invitarlas a entrar a ayudar", "Dejar el puesto para perseguirlas por la planta", "Ignorarlas"], a: 0, why: "1910.146(i): los deberes del asistente incluyen mantener fuera a las personas no autorizadas." },

  { id: "hz-26", category: "hazwoper", topic: "Especialista", q: "Un especialista en materiales peligrosos:", choices: ["Apoya a los técnicos con conocimiento más específico de las sustancias y el plan estatal, con capacitación al menos equivalente a técnico más competencias extra", "Es lo mismo que concientización", "Nunca entra a la zona tibia", "No necesita conocimiento de EPP"], a: 0, why: "1910.120(q)(6)(iv): especialista. A menudo un rol de químico o experto de industria en la escena." },
  { id: "hz-27", category: "hazwoper", topic: "Apoyo especializado", q: "El personal de apoyo especializado (p. ej., un operador de grúa llamado a una emergencia):", choices: ["Recibe una sesión informativa en el sitio de peligros, EPP y deberes antes de participar", "Necesita el curso completo de 40 horas antes de poder izar un tanque destrozado", "No necesita información", "Reemplaza al CI"], a: 0, why: "1910.120(q)(4): sesión informativa. No envíe a un operador sin informar a una pluma." },
  { id: "hz-28", category: "hazwoper", topic: "Empleado especialista", q: "Los empleados que trabajan con sustancias peligrosas solo de vez en cuando en sus trabajos regulares y pueden ser llamados a una escena:", choices: ["Necesitan capacitación sobre los peligros de esas sustancias y el plan de emergencia (empleado especialista)", "Están exentos de todo HAZWOPER", "Deben ser técnicos en todos los casos", "Solo necesitan OSHA 10"], a: 0, why: "1910.120(q)(5): empleados especialistas. Demostración anual de competencia." },
  { id: "hz-29", category: "hazwoper", topic: "Tabla 2 EPP", q: "La selección de EPP de HAZWOPER usa:", choices: ["La caracterización del sitio y los niveles 1910.120(g) / Apéndice B: no adivinar Nivel D en un foso desconocido", "Siempre el tyvek más barato", "Overoles de algodón para IDLH", "Ningún guante si se lava después"], a: 0, why: "Las atmósferas desconocidas se tratan como IDLH hasta que se caracterizan. Suba/baje de nivel con datos." },
  { id: "hz-30", category: "hazwoper", topic: "Iluminación de limpieza", q: "Las operaciones de limpieza de desechos peligrosos necesitan iluminación de al menos:", choices: ["Las bujías-pie especificadas en 1910.120 Tabla H-120.1 (p. ej., 5 fc general, más para talleres y primeros auxilios)", "Solo luz de velas", "Ninguna norma de iluminación", "Solo faros de camiones"], a: 0, why: "La gente tropieza en la oscuridad con líneas de aire y fosos. Cumpla la tabla." },

  { id: "bb-16", category: "bloodborne", topic: "Determinación de exposición", q: "La determinación de exposición en el ECP lista:", choices: ["Trabajos y tareas donde ocurre exposición ocupacional, sin considerar el EPP", "Solo nombres de clientes con VIH positivo", "Deberes del almuerzo", "Personal de oficina sin rol de primeros auxilios siempre"], a: 0, why: "1910.1030(c)(2): listas de clasificación de puestos. El EPP no es una excusa para omitir la determinación." },
  { id: "bb-17", category: "bloodborne", topic: "Prácticas de trabajo", q: "¿Cuál es una práctica de trabajo exigida?", choices: ["No reencapuchar agujas con técnica de dos manos; no comer en áreas contaminadas; minimizar las salpicaduras", "Doblar agujas a mano antes de desecharlas", "Pipetear sangre con la boca", "Zapatos abiertos en el laboratorio como EPP"], a: 0, why: "1910.1030(d)(2): prácticas de trabajo. Primero controles de ingeniería." },
  { id: "bb-18", category: "bloodborne", topic: "Lavandería", q: "La ropa de lavandería contaminada se:", choices: ["Manejará lo menos posible, embolsará en bolsas etiquetadas/con código de color y no se clasificará en el lugar de uso si expondría a otros", "La llevará el trabajador a casa para lavarla con la ropa de la familia como método preferido", "Sacudirá para quitar coágulos", "Lavará con la ropa de calle en la máquina del comedor"], a: 0, why: "1910.1030(d)(4)(iv): lavandería. La contaminación que se lleva a casa es un peligro para la familia." },
  { id: "bb-19", category: "bloodborne", topic: "Declinación", q: "Si un trabajador declina la vacuna contra hepatitis B debe:", choices: ["Firmar el formulario obligatorio de declinación; igual puede recibir la vacuna después sin costo si sigue en riesgo", "Ser despedido", "Pagar siempre la vacuna él mismo después", "Nunca volver a ofrecérsele"], a: 0, why: "El lenguaje de declinación del Apéndice A es obligatorio. Conserve el formulario." },
  { id: "bb-20", category: "bloodborne", topic: "Registro de punzocortantes", q: "Los empleadores con exposición ocupacional (salvo en ciertos estados/excepciones) mantienen un registro de lesiones por punzocortantes de:", choices: ["Lesiones percutáneas de objetos punzocortantes contaminados, con tipo/marca, área y explicación de cómo ocurrió: privacidad protegida", "Todos los cortes de papel", "Solo demandas", "Opiniones del supervisor con nombres publicados"], a: 0, why: "1910.1030(h)(5): registro de punzocortantes. Se usa para evaluar dispositivos más seguros." },

  { id: "rp-16", category: "respiratory", topic: "Administrador del programa", q: "El programa respiratorio debe tener:", choices: ["Un administrador de programa calificado que administra el programa escrito", "Ninguna persona a cargo", "Solo un proveedor", "OSHA como administrador en el sitio"], a: 0, why: "1910.134(c)(3): administrador. Necesitan suficiente conocimiento para manejar decisiones médicas, de ajuste y de cartuchos." },
  { id: "rp-17", category: "respiratory", topic: "IDLH desconocido", q: "Si el empleador no puede identificar ni estimar razonablemente la exposición, la atmósfera se considerará:", choices: ["IDLH", "Inmediatamente segura", "Solo polvo de molestia", "Enriquecida de oxígeno"], a: 0, why: "1910.134(d)(1)(iii): desconocido = IDLH. Eso impulsa SCBA/SAR hasta que tenga datos." },
  { id: "rp-18", category: "respiratory", topic: "Combate de incendios estructural interior", q: "El combate de incendios estructural interior exige:", choices: ["SCBA, sistema de compañeros y dos adentro/dos afuera según se especifica en 1910.134(g)(4)", "Mascarillas contra polvo", "Entradas de un solo bombero como estándar", "APR para humo"], a: 0, why: "Dos adentro/dos afuera. Las brigadas contra incendio también tienen 1910.156." },
  { id: "rp-19", category: "respiratory", topic: "Canister vs cartucho", q: "El APF y la duración de un canister frente a un cartucho:", choices: ["Los canisters suelen ser más grandes y se usan en máscaras de gas; igual no son para IDLH salvo que el dispositivo esté diseñado y aprobado por NIOSH para ese uso", "Los canisters siempre permiten entrada IDLH sin SCBA", "Los cartuchos suministran oxígeno", "Son idénticos en cada aprobación"], a: 0, why: "Lea la aprobación de NIOSH. Los dispositivos solo de escape no son dispositivos de entrada." },
  { id: "rp-20", category: "respiratory", topic: "Limpieza", q: "Los respiradores compartidos deben:", choices: ["Limpiarse y desinfectarse con la frecuencia necesaria para que no dañen al usuario; después de cada uso si los usan distintas personas", "Pasarse sucios", "Lavarse en gasolina", "Nunca inspeccionarse"], a: 0, why: "1910.134(h) y Apéndice B-2: procedimientos de limpieza." },

  { id: "mg-16", category: "machineguard", topic: "1910.219", q: "Los engranajes, las ruedas dentadas y las bandas deben estar:", choices: ["Resguardados si están a 7 pies o menos del piso o la plataforma de trabajo según se especifique", "Dejados abiertos para aceitar mientras corren como método preferido", "Pintados de amarillo en lugar de resguardados", "Resguardados solo por encima de 7 pies siempre y nunca por debajo"], a: 0, why: "1910.219: aparato de transmisión de potencia mecánica. Aceitar mientras está resguardado/corriendo tiene condiciones estrictas." },
  { id: "mg-17", category: "machineguard", topic: "Sierra radial", q: "Una sierra de brazo radial usada para rajar debe tener:", choices: ["El separador, los dedos anti-rechazo, y la sierra debe regresar a la posición de inicio, y no poder pasar del borde de la mesa en algunos montajes", "Ningún separador", "La hoja sin resguardo", "Un dado sin ningún control"], a: 0, why: "1910.213(h) / (s): sierras radiales. El rechazo y la sierra que camina hacia el operador." },
  { id: "mg-18", category: "machineguard", topic: "Circular portátil", q: "Las sierras circulares portátiles se equiparán con:", choices: ["Resguardos por encima y por debajo de la placa base; el resguardo inferior se retrae y regresa automáticamente", "Ningún resguardo inferior", "Una cuña que mantiene el resguardo abierto", "Hojas metálicas sin resguardo solo para mampostería como hábito"], a: 0, why: "1910.243(a)(1). La misma idea en construcción 1926.304." },
  { id: "mg-19", category: "machineguard", topic: "Servicio con bloqueo", q: "Cambiar una hoja de sierra o despejar un atasco en general requiere:", choices: ["Aislamiento de energía / LOTO, no meter la mano en una hoja viva", "Un palo mientras la sierra se detiene por inercia como único método siempre", "Ninguna protección si usted es cuidadoso", "Anular el interbloqueo de la cubierta"], a: 0, why: "Servicio vs producción. Desenchufe las herramientas pequeñas y mantenga el enchufe bajo su control, o cande el desconectador." },
  { id: "mg-20", category: "machineguard", topic: "Robótica", q: "Los robots industriales requieren:", choices: ["Resguardo, detección de presencia o celdas interbloqueadas para que los trabajadores no estén en el radio de giro; bloqueo para entrar a la celda", "Trabajadores parados en la celda durante la operación automática como estándar", "Ninguna norma de cuidado", "Solo una línea pintada"], a: 0, why: "1910.212 más la práctica ANSI/RIA R15.06. El modo de enseñanza tiene reglas de velocidad reducida. Ocurren fatalidades en las celdas." },

  { id: "ps-16", category: "psm", topic: "Apéndice A cloro", q: "La cantidad umbral de PSM del cloro en el Apéndice A es:", choices: ["1,500 libras", "10,000 libras", "100 libras", "1 libra"], a: 0, why: "1910.119 App A: cloro 1,500 lb. Un cilindro de 1 tonelada ya está por encima del TQ si está en un proceso." },
  { id: "ps-17", category: "psm", topic: "TQ de amoníaco", q: "El TQ listado del amoníaco anhidro es:", choices: ["10,000 libras", "1,500 libras", "500 libras", "100,000 libras"], a: 0, why: "App A: amoníaco 10,000 lb. Los sistemas de refrigeración pueden exceder esto fácilmente." },
  { id: "ps-18", category: "psm", topic: "Exención minorista", q: "Los líquidos inflamables usados únicamente como combustible para el consumo en el lugar de trabajo de esos combustibles (p. ej., calefacción) pueden estar:", choices: ["Exentos de PSM bajo las excepciones de 1910.119(a)(1)(ii) según se especifique", "Siempre cubiertos a 10 galones", "Cubiertos solo si es diésel", "Exentos de todo OSHA"], a: 0, why: "La exención de combustibles de hidrocarburo es estrecha. Un proceso que usa inflamables como materia prima no es “consumo en el lugar de trabajo como combustible”." },
  { id: "ps-19", category: "psm", topic: "Registro de lesiones de contratistas", q: "El anfitrión debe mantener un registro de:", choices: ["Lesiones/enfermedades de empleados contratados relacionadas con el trabajo en áreas de proceso, separado o identificado dentro del registro según se especifique", "Solo empleados del anfitrión, nunca contratistas", "Solo casi accidentes", "OSHA 300A de la ciudad"], a: 0, why: "1910.119(h)(2)(vi): registro de lesiones/enfermedades de contratistas relacionado con el trabajo del contratista en áreas de proceso." },
  { id: "ps-20", category: "psm", topic: "RAGAGEP", q: "Las Prácticas de ingeniería reconocidas y generalmente aceptadas (RAGAGEP) se usan en PSM para:", choices: ["Diseño de equipo, inspección e integridad mecánica", "Menús de cafetería", "Solo calcomanías de casco", "Ignorar códigos"], a: 0, why: "1910.119(d)(3)(ii) y (j): siga RAGAGEP o documente alternativas igualmente protectoras." },

  { id: "wd-21", category: "welding", topic: "Distancia de cilindros", q: "Los cilindros de oxígeno en almacenamiento deben separarse de los cilindros de gas combustible por 20 pies o un muro contra fuego de 5 pies. Cuando están en uso en un carrito:", choices: ["Pueden estar juntos en un carrito diseñado con los reguladores puestos, bajo las reglas de en-uso de la norma: igual mantenga el aceite lejos del oxígeno", "Pueden almacenarse de noche con reguladores puestos en un trailer cerrado como el almacenamiento preferido", "Las tapas pueden quedarse quitadas en la caja de herramientas durante semanas", "El acetileno puede acostarse de lado durante días y luego usarse de inmediato a 30 psig"], a: 0, why: "1926.350: en uso vs almacenamiento. Si van a quedarse, trátelos como almacenamiento: tapa, separe, asegure." },
  { id: "wd-22", category: "welding", topic: "Colector", q: "Los colectores de gas combustible deben estar:", choices: ["Ubicados e instalados según la norma: equipo listado, ventilación adecuada y no mezclar oxígeno y combustible en un colector", "Construidos con tes de plomería en el taller", "Colocados junto a tambores de aceite", "Usados para aumentar el acetileno por encima de 15 psig"], a: 0, why: "1926.350(e) y 1910.253: colectores. El acetileno igual tiene la regla de 15 psig." },
  { id: "wd-23", category: "welding", topic: "Flash de arco en soldadura", q: "Los ayudantes que miran el arco sin un lente pueden sufrir:", choices: ["Fotokeratitis (“flash del soldador”) horas después: pantallas y lentes de filtro para cualquiera que pueda ver el arco", "Solo un bronceado", "Ningún efecto ocular", "Mejor visión nocturna"], a: 0, why: "La UV quema la córnea. Pantallas, cortinas y letreros de advertencia." },
  { id: "wd-24", category: "welding", topic: "Extracción local", q: "La extracción local para soldadura se coloca:", choices: ["Lo más cerca practicable de la pluma para capturar los contaminantes antes de la zona de respiración", "Detrás del soldador para soplar el humo hacia su cara", "Solo en el extremo lejano del taller", "Usando oxígeno como aire de reposición"], a: 0, why: "1926.353: velocidad de captura en la fuente. No ventile con oxígeno." },
  { id: "wd-25", category: "welding", topic: "Personas de vigía de incendio", q: "Se exige un vigía de incendio cuando:", choices: ["Los combustibles están a menos de 35 pies y no pueden moverse/protegerse, u otras condiciones de 1910.252 (aberturas de muro, etc.)", "Suelda sobre un campo de tierra sin nada combustible a 100 pies y sin aberturas", "Siempre en cada estacionamiento", "Nunca si tiene una tarjeta OSHA 10"], a: 0, why: "1910.252(a)(2)(iii): condiciones que desencadenan un vigía de incendio. Al menos 30 minutos después." },

  { id: "fk-31", category: "forklift", topic: "Vías de ferrocarril", q: "Al cruzar vías de ferrocarril con un montacargas, el operador en general debe:", choices: ["Cruzar en diagonal para que no caigan ambas ruedas a la vez, a velocidad lenta", "Montarse sobre el riel a alta velocidad", "Elevar la carga al máximo", "Detenerse en las vías para revisar el teléfono"], a: 0, why: "1910.178(n)(7): cruce diagonal. Nunca estacione en las vías." },
  { id: "fk-32", category: "forklift", topic: "Pendientes cargado", q: "En pendientes, los camiones cargados deben conducirse con la carga:", choices: ["Cuesta arriba (ascenso), horquillas inclinadas hacia atrás y sin girar en la rampa si se puede evitar", "Cuesta abajo con la carga adelante siempre", "De lado", "Elevada alto para visibilidad"], a: 0, why: "1910.178(n)(7)(i): carga cuesta arriba. Mantenga el CG estable." },
  { id: "fk-33", category: "forklift", topic: "Placas de andén", q: "Las placas de andén portátiles se:", choices: ["Asegurarán en su lugar, con agarraderas u otros medios eficaces para manejarlas, y diseñadas para impedir que los vehículos se salgan del borde según se especifique", "Una placa suelta de capacidad desconocida", "Usarán aunque el trailer se haya alejado 2 pies", "Harán de madera contrachapada para camiones de 10,000 lb"], a: 0, why: "1910.178(k) / 1910.30: placas de andén. El trailer se desplaza: use sujeciones." },
  { id: "fk-34", category: "forklift", topic: "Order picker", q: "Un elevador order-picker que eleva al operador por lo general requiere:", choices: ["Protección contra caídas / sujeción del operador según exijan el fabricante y la capacitación 1910.178, más la puerta cerrada", "Pararse en las horquillas de un camión contrapesado en su lugar", "Ninguna capacitación más allá de una licencia de auto", "Viajar a alta velocidad elevado en el pasillo siempre"], a: 0, why: "Clase de camión distinta. Amarres de arnés en muchos order pickers. No mezcle la capacitación de un camión de asiento." },
  { id: "fk-35", category: "forklift", topic: "Zonas prohibidas peatonales", q: "Una carga elevada es:", choices: ["Una zona prohibida para peatones: nunca camine bajo las horquillas", "Un buen refugio de lluvia", "Segura si el operador lo ve", "Permitida si toca el mástil"], a: 0, why: "1910.178(m)(2): ninguna persona bajo la carga. La falla hidráulica deja caer las horquillas." },

  { id: "lo-26", category: "loto", topic: "Excepción de cordón", q: "La excepción de cordón y enchufe aplica solo cuando:", choices: ["Desenchufar desenergiza por completo Y el enchufe está bajo el control exclusivo del empleado que hace el trabajo", "La herramienta está cableada fija a 480 voltios", "Dos personas comparten el cordón desenchufado al otro lado del cuarto", "Un ayudante podría volver a enchufarla"], a: 0, why: "Si camina al almacén de herramientas, alguien puede enchufarla. Lleve el enchufe consigo o cándelo." },
  { id: "lo-27", category: "loto", topic: "Significado de las etiquetas", q: "Una etiqueta en un desconectador significa:", choices: ["No operar: es una advertencia, no una sujeción física; se exige bloqueo cuando el dispositivo puede aceptar un candado", "La máquina es segura para arrancar", "Reemplaza la verificación", "Cualquiera puede quitarla para poner en producción"], a: 0, why: "Las etiquetas pueden ignorarse o caerse. Los candados sujetan el dispositivo de aislamiento de energía." },
  { id: "lo-28", category: "loto", topic: "Mecánica almacenada", q: "Una caja de volteo elevada, un ramal de prensa o un resorte debe:", choices: ["Bloquearse o liberarse para que la energía de gravedad/resorte no pueda moverse durante el servicio", "Ignorarse si el motor está bloqueado", "Sostenerse por un compañero", "Confiarse solo a las válvulas de retención hidráulicas sin evaluación"], a: 0, why: "1910.147(d)(5): energía almacenada. Apuntalamiento, pasadores y disipación." },
  { id: "lo-29", category: "loto", topic: "Capacitación de afectados", q: "Los empleados afectados deben estar capacitados sobre:", choices: ["El propósito del LOTO y no arrancar equipo que está bloqueado/etiquetado", "Cómo cortar candados", "El aislamiento específico de máquina de cada válvula", "Nada"], a: 0, why: "1910.147(c)(7)(ii): concientización para que no anulen el sistema." },
  { id: "lo-30", category: "loto", topic: "Inspección periódica documentada", q: "La inspección anual de LOTO debe estar:", choices: ["Certificada (documentada) de que se inspeccionó el procedimiento y quién lo inspeccionó", "Solo verbal", "Opcional si no hay lesiones", "Hecha solo por un empleado afectado sin participación de autorizados"], a: 0, why: "1910.147(c)(6)(ii): certificación. Revise con los empleados autorizados las desviaciones." },

  { id: "hc-26", category: "hazcom", topic: "Tiempo de acceso a SDS", q: "Las SDS deben estar:", choices: ["Fácilmente accesibles durante cada turno de trabajo para los empleados cuando están en su área de trabajo", "Bajo llave en una oficina central a dos horas de distancia sin acceso fuera de horario", "Disponibles solo para supervisores", "Publicadas como un resumen de 1 página que reemplaza siempre las SDS"], a: 0, why: "1910.1200(g)(8): ninguna barrera al acceso. Los sistemas electrónicos necesitan un respaldo si la red está caída." },
  { id: "hc-27", category: "hazcom", topic: "Pictograma de calavera", q: "El pictograma de calavera y huesos indica:", choices: ["Toxicidad aguda (fatal o tóxica)", "Un oxidante", "Un gas comprimido", "Solo un irritante"], a: 0, why: "Toxicidad aguda GHS Categorías 1–3 por lo general. El signo de exclamación cubre “dañino” (Categoría 4)." },
  { id: "hc-28", category: "hazcom", topic: "Pictograma de cilindro de gas", q: "El pictograma de cilindro de gas significa:", choices: ["Gases a presión", "Explosivos", "Solo sólidos inflamables", "Toxicidad acuática"], a: 0, why: "Peligros de reventón, frío o asfixia de los cilindros. Almacene y tape correctamente." },
  { id: "hc-29", category: "hazcom", topic: "Pictograma de corrosión", q: "El pictograma de corrosión cubre:", choices: ["Corrosión de la piel, daño ocular grave y corrosión a metales", "Solo óxido en las herramientas", "Carcinógenos", "Oxidantes"], a: 0, why: "Ácidos/bases. Use los guantes correctos y lavaojos. No mezcle lejía y ácido." },
  { id: "hc-30", category: "hazcom", topic: "Acceso al programa escrito", q: "El programa escrito de HazCom debe estar:", choices: ["Disponible para los empleados, sus representantes y OSHA", "Un secreto comercial para los trabajadores", "Opcional siempre con menos de 25 empleados", "Reemplazado solo por SDS sin programa"], a: 0, why: "1910.1200(e): programa escrito. Lista de químicos, etiquetas, SDS y capacitación descritas." },

  { id: "pp-31", category: "ppe", topic: "Pago de reemplazo", q: "Cuando el EPP se desgasta por el uso en el trabajo, el empleador:", choices: ["Paga para reemplazarlo (salvo las excepciones de pago listadas, como zapatos de puntera de seguridad que no son de especialidad en algunos casos)", "Hace que el trabajador compre siempre el siguiente casco", "Cubre las grietas con cinta", "Espera hasta una lesión"], a: 0, why: "1910.132(h): reemplazo del EPP pagado por el empleador. Los artículos perdidos o dañados a propósito pueden tener políticas distintas, pero el desgaste del trabajo corre por cuenta del empleador." },
  { id: "pp-32", category: "ppe", topic: "Guantes eléctricos", q: "Los guantes aislantes de hule para trabajo eléctrico deben estar:", choices: ["Clasificados para el voltaje, inspeccionados y con prueba eléctrica periódica según se especifique (p. ej., 1910.137)", "Guantes de moda de una farmacia", "Solo cuero sin hule como protección primaria en 4 kV", "Usados después de la fecha de prueba"], a: 0, why: "Protectores de cuero sobre hule. Prueba de aire cada día. Clasificaciones de voltaje Clase 00 a 4." },
  { id: "pp-33", category: "ppe", topic: "Audición dual", q: "La protección auditiva dual (tapones más orejeras) a menudo se exige cuando:", choices: ["Las exposiciones exceden 100–105 dBA en muchos programas / la orientación del Apéndice B de OSHA para niveles altos", "El ruido es 70 dBA", "Al trabajador le gusta el aspecto", "Solo en oficinas"], a: 0, why: "1910.95: cuando las exposiciones igualan o exceden 100 dBA algunos programas exigen protección dual; la matemática de conservación auditiva de OSHA usa derating. Siga la norma y su programa." },
  { id: "pp-34", category: "ppe", topic: "Alta visibilidad de noche", q: "Los banderilleros nocturnos por lo general necesitan:", choices: ["Prendas Clase 3 o equivalentes retrorreflectantes según el MUTCD", "Una chaqueta oscura", "Ningún material retrorreflectante", "Solo un casco"], a: 0, why: "1926.201 y MUTCD Parte 6. Que lo vean o lo golpean." },
  { id: "pp-35", category: "ppe", topic: "Careta más", q: "Una careta para esmerilar:", choices: ["Se usa sobre lentes de seguridad, no en su lugar", "Reemplaza siempre los lentes Z87", "Es opcional si entrecierra los ojos", "Protege los pulmones"], a: 0, why: "El impacto puede llegar alrededor de una careta. Protección ocular primaria debajo." },

  { id: "el-31", category: "electrical", topic: "Calificado vs no calificado", q: "Los trabajadores no calificados pueden trabajar cerca de partes vivas solo:", choices: ["En o más allá de las distancias de acercamiento de las tablas: no realizan trabajo en vivo", "En una barra de 480 voltios con guantes de cuero", "Si tienen OSHA 10", "Si las partes “se ven aisladas” con pintura"], a: 0, why: "1910.333 / 1926.416: la capacitación define calificado. La pintura no es aislamiento." },
  { id: "el-32", category: "electrical", topic: "Cubiertas de receptáculos", q: "Las aberturas sin usar en gabinetes eléctricos deben estar:", choices: ["Cerradas de forma eficaz", "Dejadas abiertas para ventilación de breakers como hábito", "Cubiertas solo con cinta en lugares mojados como el método listado", "Usadas para pasar cordones extra sin accesorios"], a: 0, why: "1910.305 / 1926.405: cierre los knockouts. Acceso de dedos y herramientas a partes vivas." },
  { id: "el-33", category: "electrical", topic: "Uso extra-duro en lugar mojado", q: "Los cordones flexibles en construcción en uso mojado o extra-duro se:", choices: ["Identificarán para uso extra-duro (p. ej., tipos S, ST, SO, STO)", "Cordón de lámpara (SPT-2)", "Romex como cordón flexible a través del patio", "Cordón plano"], a: 0, why: "1926.405(a)(2)(ii)(J): uso extra-duro. Uso duro en algunos lugares secos." },
  { id: "el-34", category: "electrical", topic: "Identidad de sobrecorriente", q: "Cada desconectador y breaker debe estar:", choices: ["Marcado de forma legible para indicar su propósito salvo que esté ubicado y dispuesto de modo que el propósito sea evidente", "Sin etiqueta para que solo los electricistas sepan", "Marcado a lápiz que se borra", "Todo etiquetado “repuesto”"], a: 0, why: "1910.303(f): identificación. El LOTO depende de saber cuál breaker." },
  { id: "el-35", category: "electrical", topic: "Reset de GFCI de energía temporal", q: "Si un GFCI de construcción dispara de forma repetida, la cuadrilla debe:", choices: ["Encontrar la falla a tierra: no seguir reseteando ni anular el GFCI", "Instalar un adaptador tramposo", "Atar el botón de prueba hacia abajo", "Reemplazarlo con un adaptador sin GFCI"], a: 0, why: "El disparo es una advertencia. Herramientas mojadas y cordones cortados. Corrija la falla." },

  { id: "fp-46", category: "fallProtection", topic: "Pendiente baja definida", q: "Un techo de pendiente baja es uno con una pendiente menor o igual a:", choices: ["4 en 12 (vertical a horizontal)", "12 en 12", "Solo 1 en 12", "8 en 12"], a: 0, why: "1926.500: pendiente baja ≤ 4:12. Empinado es mayor que 4:12. Los sistemas de línea de advertencia son para techado de pendiente baja." },
  { id: "fp-47", category: "fallProtection", topic: "Opciones de techado de pendiente baja", q: "En un techo de pendiente baja de 50 pies o más de ancho, los techadores pueden usar:", choices: ["Una línea de advertencia más barandal, línea de advertencia más red de seguridad, línea de advertencia más PFAS, o línea de advertencia más vigía de seguridad (con límites)", "Ninguna protección si caminan despacio", "Solo un vigía sin línea de advertencia en un techo de 200 pies de ancho", "Cinturones de cuerpo para detención"], a: 0, why: "1926.501(b)(10): combinaciones. Los techos de menos de 50 pies de ancho pueden usar un vigía solo según se especifique." },
  { id: "fp-48", category: "fallProtection", topic: "Resistencia de la línea de advertencia", q: "Una línea de advertencia debe estar marcada al menos cada 6 pies y tener una resistencia a la tracción mínima de:", choices: ["500 libras", "50 libras", "5,000 libras", "200 libras igual que un barandal superior"], a: 0, why: "1926.502(f)(2): 500 lb de tracción, postes que resisten 16 lb, línea a 34–39 pulgadas de alto." },
  { id: "fp-49", category: "fallProtection", topic: "Desaceleración del PFAS", q: "El dispositivo de desaceleración de un PFAS detendrá por completo a un empleado y limitará la distancia de desaceleración a:", choices: ["3.5 pies", "6 pies", "12 pies", "30 pies"], a: 0, why: "1926.502(d)(16)(iii)–(iv): 3.5 pies de distancia de desaceleración y 1,800 lb de fuerza máxima de detención en el cuerpo con un arnés." },
  { id: "fp-50", category: "fallProtection", topic: "Prueba de caída de red", q: "Las redes de seguridad deben someterse a una prueba de caída en la obra:", choices: ["Después de la instalación, la reubicación y a intervalos de 6 meses, con una bolsa de arena de 400 lb de 28–32 pulgadas de diámetro dejada caer desde al menos 42 pulgadas sobre la superficie", "Nunca", "Con una persona saltando adentro", "Solo en la fábrica"], a: 0, why: "1926.502(c)(4): prueba de caída o equivalente certificado. Inspeccione las redes por escombros y daño." },

  { id: "ex-31", category: "excavation", topic: "Atmósfera peligrosa LEL", q: "Una atmósfera peligrosa en una excavación incluye gas inflamable en exceso de:", choices: ["20% del LEL (1926.651 usa 20% LEL; espacio confinado 1910.146 usa 10%: sepa cuál regla aplica)", "Solo 100% LEL", "1% de oxígeno", "El PEL de sílice"], a: 0, why: "1926.651(g): >20% del LEL es una atmósfera peligrosa en excavaciones. Los espacios con permiso usan 10% en 1910.146. Pruebe antes de entrar." },
  { id: "ex-32", category: "excavation", topic: "Rescate de emergencia", q: "Donde podría existir una atmósfera peligrosa en una excavación, el equipo de rescate de emergencia (p. ej., aparato de respiración, arnés/eslinga, camilla de canastilla) se:", choices: ["Atenderá cuando se use y estará fácilmente disponible donde se necesite", "Almacenará en el taller a 30 minutos", "Será opcional si los trabajadores pueden aguantar la respiración", "Será solo un teléfono celular"], a: 0, why: "1926.651(g)(2): equipo de rescate. No se convierta en la segunda víctima." },
  { id: "ex-33", category: "excavation", topic: "Instalación del sistema de apoyo", q: "Los sistemas de apoyo (apuntalamiento) deben instalarse:", choices: ["De forma progresiva a medida que avanza la excavación, de arriba hacia abajo, y quitarse de abajo hacia arriba salvo lo permitido", "Después de que la zanja esté totalmente abierta a la profundidad final con gente adentro", "Solo en los extremos", "Nunca en Tipo C"], a: 0, why: "1926.652(e): instalación y retiro. Los trabajadores permanecen dentro de la zona protegida." },
  { id: "ex-34", category: "excavation", topic: "Pendiente de rampa de empleados", q: "Una rampa usada para acceso de empleados con una pendiente más empinada que 4:1 (14 grados) debe tener:", choices: ["Una escalera fija o peldaños cortados en la rampa y un pasamanos si hay una caída de 6 pies o más según se especifique", "Ninguna característica extra", "Solo una soga", "Siempre una escalera de mano puesta en la tierra"], a: 0, why: "1926.651(c)(1)(v): las rampas empinadas necesitan huellas de escalera y protección contra caídas cuando la caída lo exige." },
  { id: "ex-35", category: "excavation", topic: "Estorbos de superficie", q: "Los árboles, las rocas y otros estorbos de superficie que crean un peligro se:", choices: ["Quitarían o apoyarían", "Ignorarían", "Usarían como montones de material contra el borde", "Empujarían a la zanja"], a: 0, why: "1926.651(a): estorbos de superficie. Pueden caer al hueco o sobrecargar el muro." },

  { id: "ld-28", category: "ladders", topic: "Excepción de 3 pies", q: "Si una escalera portátil no puede extenderse 3 pies por encima del descanso, usted debe:", choices: ["Asegurar la escalera y proporcionar un dispositivo para agarrarse como un pasamanos", "Pararse en la tapa superior", "Hacer que un compañero le lance una soga desde arriba como único control", "Inclinarla a 1:1"], a: 0, why: "1926.1053(b)(1): extensión de 3 pies o asegurar + dispositivo para agarrarse." },
  { id: "ld-29", category: "ladders", topic: "Doble travesaño", q: "Se exige una escalera de doble travesaño cuando:", choices: ["Una escalera es la única forma de entrar/salir de un área de trabajo con 25 o más empleados, o se espera tráfico de dos vías, según se especifique", "Cualquier vez que dos personas pudieran usar una escalera", "Nunca", "Solo en andamios"], a: 0, why: "1926.1053(a)(2): tráfico de dos vías. Ancho mínimo de 18 pulgadas entre travesaños en escaleras de doble travesaño." },
  { id: "ld-30", category: "ladders", topic: "Objetos que caen de andamio", q: "Cuando hay trabajadores debajo de un andamio, la protección contra objetos que caen incluye:", choices: ["Rodapiés, pantallas, redes de escombros, plataformas de captura, estructuras de dosel o barricadas abajo", "Solo cascos sin ningún otro control", "Gritar", "Pintar las herramientas de naranja"], a: 0, why: "1926.451(h). Rodapiés de al menos 3.5 pulgadas. Barricade el área de abajo si los objetos igual podrían caer." },
  { id: "ld-31", category: "ladders", topic: "Nieve e hielo en andamio", q: "Las condiciones resbalosas en andamios se:", choices: ["Eliminarán tan pronto como sea practicable: no trabaje en tablones cubiertos de hielo", "Ignorarán con extra cuidado", "Cubrirán con más hielo", "Serán una razón para quitar barandales"], a: 0, why: "1926.451(f)(8): nieve, hielo y condiciones resbalosas. La persona competente decide." },
  { id: "ld-32", category: "ladders", topic: "Etiqueta de andamio", q: "Muchos programas de andamio usan etiquetas verde/amarillo/rojo para mostrar:", choices: ["Inspeccionado y seguro / uso restringido / no usar: una persona competente las actualiza cada turno", "Colores de pintura", "Quién es dueño de los marcos", "Solo la velocidad del viento"], a: 0, why: "OSHA no manda estrictamente los colores de etiqueta, pero implementan las inspecciones 1926.451(f)(3). Rojo significa no subir." },

  { id: "fr-21", category: "fire", topic: "Extintores de construcción", q: "Se proporcionará un extintor clasificado no menos de 2A para cada:", choices: ["3,000 pies cuadrados de área de edificio protegida, o fracción mayor, en una obra de construcción (con reglas de distancia de recorrido)", "Siempre 100 pies cuadrados", "Todo el proyecto sin importar el tamaño, un extintor en total siempre", "Solo la oficina"], a: 0, why: "1926.150(c)(1): 2A por 3,000 pies cuadrados, distancia de recorrido 100 pies. También 2A dentro de 100 pies de cada piso en trabajo de varios pisos." },
  { id: "fr-22", category: "fire", topic: "Gas combustible en construcción", q: "No se almacenarán más de 25 galones de líquidos inflamables en un cuarto fuera de un gabinete de almacenamiento aprobado salvo que:", choices: ["El edificio esté diseñado para ese almacenamiento bajo 1926.152", "Tenga prisa", "Los líquidos estén en cubetas abiertas", "Estén etiquetados como agua"], a: 0, why: "1926.152: límites de almacenamiento interior. Las latas de seguridad, los gabinetes y las pilas de almacenamiento exterior tienen reglas extra." },
  { id: "fr-23", category: "fire", topic: "Lata de seguridad", q: "Una lata de seguridad es:", choices: ["Un recipiente cerrado aprobado de no más de 5 galones con una malla arrestallamas, tapa de cierre por resorte y cubierta de pico", "Cualquier lata de gasolina de un garage", "Una cubeta abierta de 5 galones", "Un tambor de 55 galones"], a: 0, why: "Definiciones de 1926.155 / 1910.106. Úselas para gasolina en el sitio." },
  { id: "fr-24", category: "fire", topic: "Trabajo en caliente en construcción", q: "Al soldar en las cercanías de materiales combustibles que no pueden moverse:", choices: ["Protéjalos con cubiertas y tenga vigía de incendio/extintores según exige 1926.352", "Suelde más rápido", "Empape trapos en solvente cerca", "Dependa de los rociadores futuros del edificio que aún no están cargados"], a: 0, why: "Igual que el trabajo en caliente de IG. La construcción tiene más madera, papel y aislamiento de espuma." },
  { id: "fr-25", category: "fire", topic: "Alarma en construcción", q: "Se proporcionará un sistema de alarma (teléfono, sirena, etc.) en una obra de construcción para que:", choices: ["Los empleados puedan ser alertados y se contacte a las agencias de emergencia", "Solo la radio ponga música", "Nada si siempre hay menos de 20 trabajadores", "Las alarmas estén prohibidas como una distracción"], a: 0, why: "1926.150(e) y EAP 1926.35. Publique los números." },

  { id: "hh-33", category: "health", topic: "Sílice 30 días", q: "Los datos objetivos pueden usarse en la norma de sílice para:", choices: ["Mostrar que las exposiciones permanecerán por debajo del nivel de acción bajo las condiciones descritas, a veces evitando el monitoreo", "Omitir los controles de la Tabla 1 mientras se corta en seco", "Ignorar los PEL", "Reemplazar siempre los exámenes médicos"], a: 0, why: "1926.1153(d)(2): opción de desempeño con monitoreo de aire o datos objetivos. La Tabla 1 es la otra vía." },
  { id: "hh-34", category: "health", topic: "Nivel de acción de plomo en construcción", q: "El nivel de acción de plomo en construcción es:", choices: ["30 μg/m³ como TWA de 8 horas", "50 μg/m³", "10 μg/m³", "500 μg/m³"], a: 0, why: "1926.62: AL 30, PEL 50. Las tareas desencadenantes (soldar, demolición de plomo, soldar en acero) asumen exposición hasta que tenga datos." },
  { id: "hh-35", category: "health", topic: "Persona competente de asbesto", q: "El trabajo de asbesto Clase I y II requiere una:", choices: ["Persona competente en el sitio", "Trabajador con solo OSHA 10", "Alcalde de la ciudad", "Ninguna supervisión"], a: 0, why: "1926.1101(o): inspecciones de persona competente. La capacitación es más que las tarjetas Outreach." },
  { id: "hh-36", category: "health", topic: "Generadores de CO", q: "Un generador de gasolina debe estar:", choices: ["Al aire libre, lejos de puertas/ventanas/ventilaciones: nunca en un sótano, garage o camión cerrado", "En interiores por el silencio", "En un cuarto cerrado con un ventilador soplando hacia una rendija", "Junto a la toma del calentador temporal"], a: 0, why: "Muertes por CO después de tormentas y en obras. El escape no está “justo afuera” si puede entrar." },
  { id: "hh-37", category: "health", topic: "Calor en trabajadores nuevos", q: "La mayoría de las muertes relacionadas con el calor ocurren:", choices: ["En los primeros días en el trabajo o después de regresar de un tiempo fuera: aclimate", "Después de 10 años en el mismo calor", "Solo de noche", "Solo en oficinas"], a: 0, why: "NEP de calor de OSHA. Los trabajadores nuevos reciben extra descanso y agua. Sistema de compañeros." },

  { id: "in-31", category: "intro", topic: "Acceso a registros SDS", q: "Los trabajadores tienen derecho a acceder a registros de exposición y médicos bajo:", choices: ["1910.1020 (a menudo aplicada también a la construcción)", "Solo HIPAA, nunca OSHA", "La norma de montacargas", "Solo el Formulario 300A"], a: 0, why: "1910.1020: acceso dentro de 15 días por lo general. Incluye resultados de monitoreo y SDS como registros de exposición en algunos casos." },
  { id: "in-32", category: "intro", topic: "Reporte falso", q: "Falsificar los registros de OSHA o mentir a un inspector puede llevar a:", choices: ["Sanciones penales además de civiles en casos graves", "Una nota de agradecimiento", "Nada", "Siempre solo una advertencia verbal"], a: 0, why: "17(g) de la Ley: declaraciones falsas. 11(c) por represalias. Mantenga registros honestos." },
  { id: "in-33", category: "intro", topic: "Pago del recorrido", q: "Los representantes de empleados en un recorrido de OSHA:", choices: ["En general se les paga como se les pagaría por tiempo de trabajo bajo la política/interpretaciones de OSHA cuando participan", "Deben usar siempre días de vacaciones", "Están prohibidos", "Solo los gerentes pueden recorrer"], a: 0, why: "La Ley contempla la participación de los empleados. La regla/política reciente de recorrido de OSHA ha sido litigada: los trabajadores igual tienen derecho a participar." },
  { id: "in-34", category: "intro", topic: "Capacitación Focus Four", q: "OSHA 10 Construcción debe incluir:", choices: ["Horas especificadas sobre Focus Four y otros temas obligatorios en las directrices del Outreach Training Program", "Solo videos sin discusión", "Cualquier 10 horas de charlas de caja de herramientas sin reglas de instructor autorizado", "Un examen que emite una tarjeta del DOL sin instructor"], a: 0, why: "Los instructores autorizados siguen los esquemas de temas de OSHA. Esta app de práctica no reemplaza ese curso." },
  { id: "in-35", category: "intro", topic: "OSHA 30 vs 10", q: "OSHA 30 Construcción comparado con OSHA 10:", choices: ["Añade temas de supervisión y más peligros (horas electivas) y son 30 horas de contacto con un instructor autorizado", "Es el mismo examen con una calcomanía distinta", "Es una licencia federal para dirigir cualquier demolición", "Vence a diario"], a: 0, why: "Las 30 horas siguen siendo concientización, no una tarjeta de Persona competente por sí sola. El empleador igual capacita sobre peligros específicos del sitio." },

  { id: "rk-21", category: "recordkeeping", topic: "Lista de primeros auxilios", q: "¿Cuál es tratamiento médico (por lo general registrable), no primeros auxilios?", choices: ["Usar dispositivos de cierre de heridas como suturas, grapas o pegamento quirúrgico", "Vendas mariposa / Steri-Strips", "Una bolsa de frío", "Beber líquidos para alivio del estrés por calor como primeros auxilios listados"], a: 0, why: "1904.7(b)(5): las Steri-Strips son primeros auxilios; las suturas/grapas/pegamento son tratamiento médico." },
  { id: "rk-22", category: "recordkeeping", topic: "Receta", q: "Una sola dosis de medicamento con receta es:", choices: ["Tratamiento médico: registrable si está relacionado con el trabajo", "Primeros auxilios", "Nunca registrable", "Solo registrable si son tres dosis"], a: 0, why: "Incluso una dosis con receta es tratamiento médico bajo la Parte 1904 (con una excepción estrecha para algunos medicamentos preventivos: siga el texto)." },
  { id: "rk-23", category: "recordkeeping", topic: "Pérdida del conocimiento", q: "La pérdida del conocimiento relacionada con el trabajo es:", choices: ["Registrable sin importar cuánto dure", "Registrable solo si es de más de 5 minutos", "Primeros auxilios", "Nunca registrable si regresan al trabajo"], a: 0, why: "1904.7(b)(6): cualquier pérdida del conocimiento." },
  { id: "rk-24", category: "recordkeeping", topic: "Trabajo restringido", q: "Trabajo restringido significa que el empleado no puede:", choices: ["Realizar una o más funciones rutinarias del puesto o trabajar un día completo por la lesión, según lo asigne el empleador o el PLHCP", "Solo que se perdió un turno extra favorito por elección", "Que se le dio un trabajo más duro", "Un día de vacaciones"], a: 0, why: "1904.7(b)(4): trabajo restringido / transferencia de puesto. El trabajo ligero igual cuenta." },
  { id: "rk-25", category: "recordkeeping", topic: "Conteo de días", q: "Al contar los días de baja, usted incluye:", choices: ["Días calendario, no solo días de trabajo programados, con un tope de 180 días para fines de registro", "Solo sábados", "Años ilimitados en la línea del registro", "Solo el día de la lesión, nunca días posteriores"], a: 0, why: "1904.7(b)(3): tope de 180 días. El día de la lesión no se cuenta como un día de baja." }
];
